// ============================================================
// FUNZIONI DI SUPPORTO (adattate dalla logica originale dell'app Snack)
// ============================================================

function searchAllMotu(query) {
  const q = (query || '').toLowerCase().trim();
  if (!q) return [];
  const results = [];
  Object.entries(CATALOG).forEach(([serie, subs]) => {
    Object.entries(subs).forEach(([sub, items]) => {
      items.forEach(item => {
        if (item.name.toLowerCase().includes(q) || (item.sku && item.sku.toLowerCase().includes(q)) || (item.ean && item.ean.includes(q))) {
          results.push({ ...item, serie, sub });
        }
      });
    });
  });
  return results;
}

// Genera la lista per la pagina Collection Value
// ── VALORE COLLEZIONE ──
// Tutti i prezzi nel catalogo sono in USD (valori medi per pezzi in buone condizioni).
// Se per un pezzo manca il prezzo loose/MOC si usa il prezzo retail come stima.
// Per ogni pezzo posseduto l'utente sceglie come lo tiene: LOOSE oppure MOC (flag v-loose-<id> / v-moc-<id>);
// senza scelta si conta LOOSE. Le copie doppie contano tutte nella stessa condizione.
window.MOTU_CONFIG = window.MOTU_CONFIG || { usdToEur: 0.92, valuesUpdated: 'October 2026' };
function getValueRowsMotu(ownedIds, valueIds, qtyIds) {
  qtyIds = qtyIds || {};
  valueIds = valueIds || {};
  const qty = id => Math.max(1, Math.min(99, parseInt(qtyIds[id], 10) || 1));
  const px = (v, item, kind) => {
    const p = kind === 'moc' ? v.priceMOC : v.priceLoose;
    return p > 0 ? p : (item.priceRetail > 0 ? item.priceRetail : 0);
  };
  const rows = [];
  Object.entries(CATALOG).forEach(([serie, subs]) => {
    Object.entries(subs).forEach(([sub, items]) => {
      items.forEach(item => {
        const vs = Array.isArray(item.variants) ? item.variants : [];
        const ownedVariants = vs.filter(v => ownedIds[v.id]);
        let units = [];
        if (ownedVariants.length) units = ownedVariants.map(v => ({ obj: v, id: v.id, variant: v.name }));
        else if (ownedIds[item.id]) units = [{ obj: item, id: item.id, variant: '-' }];
        units.forEach(u => {
          const looseKey = `v-loose-${u.id}`, mocKey = `v-moc-${u.id}`;
          const mocOn = !!valueIds[mocKey];
          const looseOn = !!valueIds[looseKey] || !mocOn;   // senza scelta: loose
          const priceLoose = px(u.obj, item, 'loose'), priceMOC = px(u.obj, item, 'moc');
          const total = ((looseOn ? priceLoose : 0) + (mocOn ? priceMOC : 0)) * qty(u.id);
          rows.push({
            key: u.id, name: item.name, year: item.year || '-', wave: item.wave || '-',
            variant: u.variant, priceLoose, priceMOC, looseKey, mocKey, looseOn, mocOn, total, serie, sub, qty: qty(u.id),
          });
        });
      });
    });
  });
  return rows;
}
// Valore totale (USD) dei pezzi segnati
function getCollectionValueMotu(ownedIds, valueIds, qtyIds) {
  return getValueRowsMotu(ownedIds, valueIds, qtyIds).reduce((sum, r) => sum + r.total, 0);
}

// Ripartizione per condizione: quanti pezzi (copie incluse) sono LOOSE e quanti MOC, e quanto valgono.
function getConditionStatsMotu(ownedIds, valueIds, qtyIds) {
  const out = { looseCount: 0, mocCount: 0, looseValue: 0, mocValue: 0 };
  getValueRowsMotu(ownedIds, valueIds, qtyIds).forEach(r => {
    if (r.mocOn) { out.mocCount += r.qty; out.mocValue += r.priceMOC * r.qty; }
    else { out.looseCount += r.qty; out.looseValue += r.priceLoose * r.qty; }
  });
  out.looseValue = Math.round(out.looseValue); out.mocValue = Math.round(out.mocValue);
  return out;
}

function getItemsMotu(serie, sub) {
  if (!serie) return [];
  const serieData = CATALOG[serie];
  if (!serieData) return [];
  if (sub) return serieData[sub] || [];
  return Object.values(serieData).flat();
}

function getStatsMotu(ownedIds, serie, sub, qtyIds) {
  qtyIds = qtyIds || {};
  const qty = id => Math.max(1, Math.min(99, parseInt(qtyIds[id], 10) || 1));
  const scope = serie ? getItemsMotu(serie, sub) : [].concat(...Object.values(CATALOG).map(s => [].concat(...Object.values(s))));
  const total = scope.length;
  const owned = scope.filter(i => ownedIds[i.id]).length;
  // Pezzi: l'unità e' la variante (se ne hai segnata almeno una) oppure il personaggio.
  let unique = 0, pieces = 0;
  scope.forEach(i => {
    if (!ownedIds[i.id]) return;
    const vOwned = (i.variants || []).filter(v => ownedIds[v.id]);
    if (vOwned.length) { unique += vOwned.length; vOwned.forEach(v => { pieces += qty(v.id); }); }
    else { unique += 1; pieces += qty(i.id); }
  });
  return { total, owned, missing: total - owned, pct: total ? Math.round(owned / total * 100) : 0, unique, doubles: pieces - unique, pieces };
}

// Foto: se esiste photos.js (generato da prepara_foto.py) assegna foto, scaffale e testina ai personaggi
(function () {
  const P = window.MOTU_PHOTOS;
  if (!P) return;
  Object.values(CATALOG).forEach(subs => Object.values(subs).forEach(items => items.forEach(it => {
    const p = P[it.id];
    if (!p) return;
    if (p.images && p.images.length) it.images = p.images;
    if (p.preview) it.preview = p.preview;
    if (p.thumb) it.thumb = p.thumb;
  })));
})();

// Prezzi: se esiste prices.js (generato dal pannello admin) assegna prezzo loose/MOC (USD) ai pezzi e alle varianti
(function () {
  const P = window.MOTU_PRICES;
  if (!P) return;
  const apply = (o) => {
    const p = P[o.id];
    if (!p) return;
    if (p.l > 0) o.priceLoose = p.l;
    if (p.m > 0) o.priceMOC = p.m;
  };
  Object.values(CATALOG).forEach(subs => Object.values(subs).forEach(items => items.forEach(it => {
    apply(it);
    (it.variants || []).forEach(apply);
  })));
})();

